def count_caches(self):
    if self.cache_head is None and self.cache_tail is None:
        return 0
    elif self.cache_head == self.cache_tail:
        return 1
    else:
        count = 0
        current = self.cache_head
        while current is not None:
            count += 1
            current = current.nxt
        return count
